import{_ as o,o as e,c as a,ae as i}from"./chunks/framework.vXWZTEWX.js";const p=JSON.parse('{"title":"✍️ Microcopy & UX Writing Standards - TenderCheck AI","description":"","frontmatter":{},"headers":[],"relativePath":"standards/microcopy_policy.md","filePath":"standards/microcopy_policy.md"}'),n={name:"standards/microcopy_policy.md"};function r(s,t,c,l,d,u){return e(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="✍️-microcopy-ux-writing-standards-tendercheck-ai" tabindex="-1">✍️ Microcopy &amp; UX Writing Standards - TenderCheck AI <a class="header-anchor" href="#✍️-microcopy-ux-writing-standards-tendercheck-ai" aria-label="Permalink to &quot;✍️ Microcopy &amp; UX Writing Standards - TenderCheck AI&quot;">​</a></h1><h2 id="_1-tone-and-voice" tabindex="-1">1. Tone and Voice <a class="header-anchor" href="#_1-tone-and-voice" aria-label="Permalink to &quot;1. Tone and Voice&quot;">​</a></h2><ul><li><strong>Professional yet Approachable</strong>: The AI should sound like a senior technical auditor—precise and serious, but helpful.</li><li><strong>Active Voice</strong>: Use active verbs for buttons and calls to action (e.g., &quot;Analyze Documents&quot; instead of &quot;Document Analysis Is Starting&quot;).</li><li><strong>Consistency</strong>: Use the same terminology throughout the app (e.g., if you call it a &quot;Tender,&quot; don&#39;t switch to &quot;Contract&quot; or &quot;Licitación&quot; in the UI).</li></ul><h2 id="_2-ai-interaction-copy" tabindex="-1">2. AI Interaction Copy <a class="header-anchor" href="#_2-ai-interaction-copy" aria-label="Permalink to &quot;2. AI Interaction Copy&quot;">​</a></h2><ul><li><strong>Visibility of Status</strong>: Use descriptive text during processing, such as &quot;Scanning Pliego for requirements...&quot; or &quot;Comparing Offer with Article 4...&quot;.</li><li>[cite_start]<strong>Transparency</strong>: When the AI is unsure, use phrases like: &quot;I found a potential match, but it requires human verification&quot;[cite: 70, 915].</li><li><strong>Avoid &quot;Robot Speak&quot;</strong>: Instead of &quot;Error 500: Execution failed,&quot; use &quot;Something went wrong while reading the PDF. Please try uploading a clearer version.&quot;</li></ul><h2 id="_3-feedback-and-guidance" tabindex="-1">3. Feedback and Guidance <a class="header-anchor" href="#_3-feedback-and-guidance" aria-label="Permalink to &quot;3. Feedback and Guidance&quot;">​</a></h2><ul><li><strong>Actionable Tooltips</strong>: Every icon should have a tooltip explaining its function in plain English.</li><li><strong>Empty States</strong>: If no analysis exists yet, don&#39;t show a blank screen. Use: &quot;Ready to start? Upload your first Pliego and Offer to begin the validation.&quot;</li><li><strong>Loading States</strong>: During long wait times, use microcopy to manage expectations: &quot;This usually takes 30 seconds for large documents&quot;.</li></ul><h2 id="_4-accessibility-and-microcopy" tabindex="-1">4. Accessibility and Microcopy <a class="header-anchor" href="#_4-accessibility-and-microcopy" aria-label="Permalink to &quot;4. Accessibility and Microcopy&quot;">​</a></h2><ul><li><strong>Descriptive ARIA Labels</strong>: Buttons should have labels that describe the result of the action (e.g., <code>aria-label=&quot;Download final validation report in PDF&quot;</code>).</li><li><strong>Inclusive Language</strong>: Avoid technical jargon that isn&#39;t industry-standard; prioritize clarity for all levels of users.</li></ul>',9)])])}const g=o(n,[["render",r]]);export{p as __pageData,g as default};
